import{_ as o}from"./chunks/35-inpaint-before-after.zzj8j6F4.js";import{_ as s,o as r,c as n,a2 as a}from"./chunks/framework.CXsxtpvq.js";const l="/asset-studio/shots/29-gallery-send-to-tools.webp",e="/asset-studio/shots/31-tools-analysis.webp",i="/asset-studio/shots/36-tools-tags.webp",g="/asset-studio/shots/33-tools-inpaint.webp",d="/asset-studio/shots/38-tools-alpha-preview.webp",p="/asset-studio/shots/39-tools-censor.webp",k=JSON.parse('{"title":"이미지 도구","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/tools.md","filePath":"ko/guide/tools.md"}'),h={name:"ko/guide/tools.md"};function c(u,t,m,_,b,P){return r(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="이미지-도구" tabindex="-1">이미지 도구 <a class="header-anchor" href="#이미지-도구" aria-label="Permalink to &quot;이미지 도구&quot;">​</a></h1><p><strong>이미지 도구</strong>는 한 장 한 장 손보는 작업을 모아 둔 곳입니다. 원본은 절대 바뀌지 않고 결과는 늘 새 파일로 저장됩니다.</p><h2 id="이미지-넣기" tabindex="-1">이미지 넣기 <a class="header-anchor" href="#이미지-넣기" aria-label="Permalink to &quot;이미지 넣기&quot;">​</a></h2><ul><li><strong>파일·ZIP 올리기</strong>: PNG, WebP, JPEG 파일이나 그 파일들을 담은 ZIP을 올립니다. 화면에 끌어다 놓아도 됩니다.</li><li><strong>갤러리에서 보내기</strong>: 갤러리에서 이미지를 고르고 <strong>이미지 도구로 보내기</strong>를 누릅니다.</li></ul><p><img src="'+l+'" alt="갤러리에서 보내기"></p><p>왼쪽 목록에서 이미지를 누르면 가운데에 이미지와 제작 정보가 나옵니다. Asset Studio 기록, ComfyUI 그래프, A1111 <code>parameters</code>, EXIF를 읽어 프롬프트와 설정을 보여 주고, <strong>실험실에서 열기</strong>로 그대로 실험실에 넘길 수 있습니다.</p><p><img src="'+e+'" alt="제작 정보 읽기"></p><p>체크한 이미지는 <strong>ZIP 내려받기</strong>로 한 번에 받을 수 있습니다.</p><h2 id="결과는-어디에-저장되나" tabindex="-1">결과는 어디에 저장되나 <a class="header-anchor" href="#결과는-어디에-저장되나" aria-label="Permalink to &quot;결과는 어디에 저장되나&quot;">​</a></h2><ul><li>작업 이미지(작품/캐릭터/의상 폴더의 이미지)의 결과는 <strong>원본 옆에 새 후보로</strong> 저장됩니다. 예를 들어 <code>002.png</code>를 인페인트하면 <code>002_inpaint.png</code>가 생깁니다. 갤러리에서 통과시키면 그 감정의 채택본이 됩니다.</li><li>올린 이미지나 실험실 이미지의 결과는 <code>outputs/_tools/&lt;날짜&gt;/</code>에 저장됩니다.</li></ul><h2 id="태그-분석" tabindex="-1">태그 분석 <a class="header-anchor" href="#태그-분석" aria-label="Permalink to &quot;태그 분석&quot;">​</a></h2><p>WD14 태거로 이미지에서 태그를 읽고 그 이미지의 프롬프트와 비교합니다.</p><p><img src="'+i+'" alt="태그 분석 결과"></p><ul><li><strong>프롬프트와 일치</strong>: 프롬프트에 있고 그림에서도 읽힌 태그.</li><li><strong>그림에서만 읽힘</strong>: 프롬프트에는 없지만 그림에 나타난 태그. 의도하지 않은 요소를 찾을 때 봅니다.</li><li><strong>그림에서 안 읽힘</strong>: 프롬프트에는 있지만 그림에서 읽히지 않은 태그. 그려지지 않았거나 태거가 모르는 표현입니다.</li></ul><p><strong>태그 복사</strong>, <strong>태그로 실험실 열기</strong>를 쓸 수 있습니다. 오른쪽 <strong>제외할 태그</strong>에 적은 태그는 화면·복사· 내보내기에서 모두 빠집니다. <strong>태그 내보내기</strong>의 TXT는 이미지마다 캡션 파일 하나를 이미지 ZIP과 같은 이름으로 묶어 줍니다(LoRA 학습용).</p><p>태그 분석은 생성 대기열을 함께 쓰므로 생성 중인 이미지가 끝난 뒤 실행됩니다.</p><h2 id="인페인트" tabindex="-1">인페인트 <a class="header-anchor" href="#인페인트" aria-label="Permalink to &quot;인페인트&quot;">​</a></h2><p>칠한 부분만 그 이미지의 모델·LoRA·프롬프트로 다시 그립니다. 손 모양이나 소품처럼 일부만 고치고 싶을 때 씁니다. Asset Studio로 만든(제작 기록이 있는) 이미지에만 쓸 수 있습니다.</p><p><img src="'+g+'" alt="인페인트 마스크"></p><ol><li><strong>다시 그릴 부분</strong>을 초록 브러시로 칠하고 <strong>마스크 저장</strong>을 누릅니다.</li><li><strong>프롬프트</strong>는 이미지 기록의 프롬프트로 채워져 있습니다. 고칠 부분을 설명하는 태그를 더해도 됩니다.</li><li><strong>다시 그릴 영역</strong>을 고릅니다. <ul><li><strong>마스크 주변만 크게 (권장)</strong>: 마스크 주변을 잘라 생성 크기로 키워 그린 뒤 다시 붙입니다. 손가락처럼 작은 부분이 더 또렷해집니다. <strong>주변 여백</strong>이 넓을수록 주변과 잘 어울립니다.</li><li><strong>이미지 전체</strong>: 이미지 크기 그대로 그립니다.</li></ul></li><li><strong>디노이즈</strong>를 정합니다. 높을수록 많이 바뀝니다. 손·소품은 0.5~0.7부터 시작하세요.</li><li><strong>현재 이미지 인페인트</strong>를 누릅니다.</li></ol><p>칠하지 않은 부분은 원본 픽셀 그대로 남습니다.</p><p><img src="'+o+'" alt="인페인트 전후"></p><h2 id="배경-투명화" tabindex="-1">배경 투명화 <a class="header-anchor" href="#배경-투명화" aria-label="Permalink to &quot;배경 투명화&quot;">​</a></h2><ol><li><strong>배경 분리</strong>: isnet-anime(애니 일러스트용) 또는 인물 분할로 남길 부분을 자동으로 찾습니다.</li><li><strong>마스크 고치기</strong>: 파란 부분이 남는 영역입니다. 브러시로 더하고 지우개로 덜어 낸 뒤 저장합니다. <strong>결과 미리보기</strong>를 켜면 잘린 모습을 바로 볼 수 있습니다.</li><li><strong>적용</strong>: 마스크 확장과 경계 부드럽게를 정하고 적용하면 투명 배경 PNG가 저장됩니다.</li></ol><p><img src="'+d+'" alt="배경 투명화 미리보기"></p><p>업스케일하면 투명도가 사라지므로, 배경 투명화는 업스케일한 뒤에 하세요.</p><h2 id="가림-처리" tabindex="-1">가림 처리 <a class="header-anchor" href="#가림-처리" aria-label="Permalink to &quot;가림 처리&quot;">​</a></h2><ol><li><strong>부위 검출</strong>(선택): 가릴 부위를 자동으로 찾습니다. 놓칠 수 있으니 꼭 확인하세요.</li><li><strong>마스크 고치기</strong>: 빨간 부분이 가려집니다. 검출 없이 직접 칠해도 됩니다.</li><li><strong>적용</strong>: 모자이크, 흐림, 단색 중에서 고르고 강도·색·마스크 확장·경계 부드럽게를 정합니다.</li></ol><p><img src="'+p+'" alt="가림 처리"></p><p>가림 처리와 배경 투명화는 <strong>마스크가 있는 선택 이미지 N장에 적용</strong>으로 여러 장에 한 번에 적용할 수 있습니다. 이미지마다 저장된 자기 마스크를 씁니다.</p><h2 id="마스크-편집기" tabindex="-1">마스크 편집기 <a class="header-anchor" href="#마스크-편집기" aria-label="Permalink to &quot;마스크 편집기&quot;">​</a></h2><p>인페인트·배경 투명화·가림 처리는 같은 편집기를 씁니다.</p><table tabindex="0"><thead><tr><th>조작</th><th>방법</th></tr></thead><tbody><tr><td>브러시 / 지우개</td><td><strong>B</strong> / <strong>E</strong></td></tr><tr><td>브러시 크기</td><td><strong>[</strong> / <strong>]</strong> 또는 크기 막대</td></tr><tr><td>되돌리기 / 다시 실행</td><td><strong>Ctrl+Z</strong> / <strong>Ctrl+Y</strong></td></tr><tr><td>확대·축소</td><td>마우스 휠</td></tr><tr><td>화면 이동</td><td><strong>스페이스바</strong>를 누른 채 끌기, 또는 가운데 버튼 끌기</td></tr><tr><td>화면에 맞춤 / 100%</td><td><strong>0</strong> / <strong>1</strong></td></tr></tbody></table><p><strong>마스크 표시</strong>와 투명도 막대로 마스크를 숨기거나 흐리게 볼 수 있고, <strong>배경</strong>으로 투명한 부분 뒤에 체커·흰색·검정 중 무엇을 깔지 고릅니다.</p><h2 id="후처리" tabindex="-1">후처리 <a class="header-anchor" href="#후처리" aria-label="Permalink to &quot;후처리&quot;">​</a></h2><ul><li><strong>업스케일</strong>: 업스케일 모델로 키우고 원하는 최종 배율로 맞춥니다.</li><li><strong>디테일러</strong>(실험): 얼굴, 눈, 입, 손을 찾아 그 이미지의 모델로 다시 그립니다. 얼굴 인상이 바뀔 수 있으니 결과를 확인하세요.</li></ul><h2 id="webp-변환" tabindex="-1">WebP 변환 <a class="header-anchor" href="#webp-변환" aria-label="Permalink to &quot;WebP 변환&quot;">​</a></h2><p>품질, 무손실, 긴 변 크기를 정해 WebP로 바꿉니다. <strong>메타데이터 유지</strong>는 기본으로 꺼져 있어 공유하는 파일에 프롬프트와 워크플로가 남지 않습니다.</p>',38)])])}const x=s(h,[["render",c]]);export{k as __pageData,x as default};
